from pathlib import Path
ROOT=Path(r'C:\Users\27933\.codex\worktrees\architecture-convergence-recovered\ClawX');RUN=Path(__file__).parent
OUT=RUN/'revalidation';OUT.mkdir(exist_ok=True)
def git(*a):return subprocess.check_output(['git',*a],cwd=ROOT).decode('utf-8').strip()
assert not git('status','--porcelain')
candidate={'commit':git('rev-parse','HEAD'),'tree':git('rev-parse','HEAD^{tree}'),'dirty':False}
assert not git('diff','23d53a29a','HEAD','--','src','electron','shared','openclaw_runtime','tests','scripts','package.json','pnpm-lock.yaml')
env={**os.environ,'TEMP':'D:/tmp','TMP':'D:/tmp','TMPDIR':'D:/tmp','GOMAXPROCS':'4','UV_THREADPOOL_SIZE':'2','COMMS_OUTPUT_DIR':str(OUT/'comms')}
spec='harness/specs/tasks/architecture-review-and-integration.md'
commands=[('versebrowser-types',['node','node_modules/typescript/bin/tsc','-p','packages/versebrowser/tsconfig.build.json']),*[('types-'+n,['node','node_modules/@typescript/native-preview/bin/tsgo.js','--noEmit','-p','tsconfig.'+n+'.json','--composite','false']) for n in ('node','web','test')],('contract',['node','scripts/contract-check.mjs']),('authority',['node','scripts/check-semantic-authority.mjs','--report',str(OUT/'authority.json'),'--actor','codex-architecture-review']),('evidence-report',['node','scripts/check-evidence-refs.mjs','--report',str(OUT/'evidence-report.json'),'--actor','codex-architecture-review']),('evidence-verify',['node','scripts/check-evidence-refs.mjs','--verify',str(OUT/'evidence-report.json')]),('comms-replay',['node','scripts/comms/replay.mjs']),('comms-compare',['node','scripts/comms/compare.mjs']),('retention',['node','scripts/check-repository-artifacts.mjs']),('harness-validate',['node','harness/src/cli.mjs','validate','--spec',spec]),('harness-dry-run',['node','harness/src/cli.mjs','run','--spec',spec,'--dry-run']),('diff',['git','diff','--check','main'])]
records=[]
for name,argv in commands:
 start=time.monotonic();started=dt.datetime.now(dt.timezone.utc).isoformat()
 with (OUT/(name+'.stdout.txt')).open('wb') as stdout,(OUT/(name+'.stderr.txt')).open('wb') as stderr:
  proc=subprocess.Popen(argv,cwd=ROOT,env=env,stdout=stdout,stderr=stderr)
  while proc.poll() is None:
   try:proc.wait(timeout=30)
   except subprocess.TimeoutExpired:print(json.dumps({'running':name,'pid':proc.pid,'seconds':round(time.monotonic()-start)}),flush=True)
 item={'id':name,'argv':argv,'cwd':str(ROOT),'candidate':candidate,'exitCode':proc.returncode,'startedAt':started,'durationSeconds':round(time.monotonic()-start,3)}
 for stream in ('stdout','stderr'):
  raw=(OUT/(name+'.'+stream+'.txt')).read_bytes();item[stream]={'sha256':hashlib.sha256(raw).hexdigest(),'text':raw.decode('utf-8')}
 records.append(item);(OUT/'gates.json').write_text(json.dumps({'driven_by':'agent','actor':'codex-architecture-review','candidate':candidate,'sourceEquivalentToTested':'23d53a29a6a4fb53b3c76670589796bb5d710ce3','gates':records},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 assert not git('status','--porcelain') and git('rev-parse','HEAD')==candidate['commit']
 print(json.dumps({'id':name,'exitCode':proc.returncode,'seconds':item['durationSeconds']}),flush=True)
raise SystemExit(int(any(r['exitCode'] for r in records)))

import hashlib,json,subprocess,sys
from pathlib import Path
MAIN=Path(r'D:\ClawX');OUT=Path(__file__).parent/'merge-plan';OUT.mkdir(exist_ok=True)
target=sys.argv[1]
def git(*a):return subprocess.check_output(['git',*a],cwd=MAIN)
old=git('rev-parse','HEAD').decode().strip();new=git('rev-parse',target).decode().strip()
assert subprocess.run(['git','merge-base','--is-ancestor',old,new],cwd=MAIN).returncode==0,'Candidate must include current main.'
assert not git('diff','--cached','--name-only').strip(),'Preserve an unexpected staged main index; do not perform merge.'
incoming=set(git('diff','--name-only','-z',old,new).decode().strip('\0').split('\0'))
dirty=set(git('diff','--name-only','-z').decode().strip('\0').split('\0'))-{''}
overlap=sorted(incoming&dirty)
checks=[];saved=[]
for name in sorted(dirty):
 p=MAIN/name
 if p.is_file():checks.append({'path':name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
 else:checks.append({'path':name,'missing':True})
for i,name in enumerate(overlap):
 original=(MAIN/name).read_bytes();base=git('show',old+':'+name);theirs=git('show',new+':'+name)
 paths=[OUT/(str(i)+suffix) for suffix in ('.local','.base','.incoming')]
 for p,b in zip(paths,(original,base,theirs)):p.write_bytes(b)
 merged=subprocess.run(['git','merge-file','--stdout',*[str(p) for p in paths]],cwd=MAIN,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
 if merged.returncode:raise RuntimeError('Uncommitted overlap needs resolution: '+name)
 combined=OUT/(str(i)+'.combined');combined.write_bytes(merged.stdout)
 saved.append({'path':name,'before':str(paths[0]),'base':str(paths[1]),'new':str(paths[2]),'combined':str(combined),'beforeSha256':hashlib.sha256(original).hexdigest(),'combinedSha256':hashlib.sha256(merged.stdout).hexdigest()})
plan={'oldMain':old,'target':new,'incomingCount':len(incoming),'dirtyPaths':checks,'overlap':saved,'untrackedBefore':git('ls-files','--others','--exclude-standard','-z').decode().strip('\0').split('\0'),'note':'Plan only. No working file or Git index changed; overlap combined with git merge-file from original bytes.'}
(OUT/'plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'main':old,'target':new,'changed':len(incoming),'dirty':len(dirty),'overlap':overlap,'status':'reviewable-plan'},ensure_ascii=False))
